begin;
create table public.internal_trackers(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),client_id uuid not null,project_id uuid not null,
 title text not null check(length(trim(title)) between 1 and 160),document_id text not null,revision text not null,source_name text not null,source_text text not null check(length(source_text)<=150000),sla text not null default '' check(length(sla)<=10000),request_id uuid not null,fingerprint text not null,created_by uuid not null default auth.uid(),created_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,client_id),unique(tenant_id,project_id),unique(tenant_id,request_id),unique(tenant_id,fingerprint),foreign key(tenant_id,client_id) references public.clients(tenant_id,id),foreign key(tenant_id,project_id) references public.projects(tenant_id,id));
create table public.internal_tracker_tasks(
 tenant_id uuid not null,tracker_id uuid not null,task_id uuid not null,task_key text not null,priority text not null default 'P1' check(priority in ('P0','P1','P2','P3')),checks jsonb not null default '[]' check(jsonb_typeof(checks)='array'),notes text not null default '' check(length(notes)<=15000),evidence text not null default '' check(length(evidence)<=15000),version integer not null default 1,
 primary key(tenant_id,task_id),unique(tenant_id,tracker_id,task_key),foreign key(tenant_id,tracker_id) references public.internal_trackers(tenant_id,id),foreign key(tenant_id,task_id) references public.tasks(tenant_id,id));
alter table public.internal_trackers enable row level security;alter table public.internal_tracker_tasks enable row level security;
create policy tracker_read on public.internal_trackers for select to authenticated using(public.is_staff(tenant_id));
create policy tracker_create on public.internal_trackers for insert to authenticated with check(public.is_staff(tenant_id) and created_by=auth.uid() and public.has_capability(tenant_id,'crm') and public.has_capability(tenant_id,'delivery'));
create policy tracker_tasks_read on public.internal_tracker_tasks for select to authenticated using(public.is_staff(tenant_id));
create policy tracker_tasks_create on public.internal_tracker_tasks for insert to authenticated with check(public.is_staff(tenant_id) and public.has_capability(tenant_id,'crm') and public.has_capability(tenant_id,'delivery'));
create policy tracker_tasks_edit on public.internal_tracker_tasks for update to authenticated using(public.is_staff(tenant_id) and (public.has_capability(tenant_id,'delivery') or exists(select 1 from public.tasks x where x.tenant_id=internal_tracker_tasks.tenant_id and x.id=task_id and x.assignee_id=auth.uid()))) with check(public.is_staff(tenant_id));
revoke all on public.internal_trackers,public.internal_tracker_tasks from public,anon,authenticated;
grant select,insert on public.internal_trackers,public.internal_tracker_tasks to authenticated;grant update(notes,evidence,checks,priority,version) on public.internal_tracker_tasks to authenticated;
create index internal_tracker_tasks_tracker_idx on public.internal_tracker_tasks(tenant_id,tracker_id);
-- This invariant must see the registry even when a client cannot select it.
create function nxt_private.guard_internal_tracker_work() returns trigger language plpgsql security definer set search_path='' as $$declare r public.internal_trackers;begin
 if tg_table_name='projects' then select * into r from public.internal_trackers where tenant_id=new.tenant_id and project_id=new.id;
 else select a.* into r from public.internal_trackers a join public.internal_tracker_tasks b on b.tenant_id=a.tenant_id and b.tracker_id=a.id where b.tenant_id=new.tenant_id and b.task_id=new.id;end if;
 if r.id is not null then if new.client_visible or new.client_id is distinct from r.client_id then raise exception 'This tracker and its work are internal only';end if;if tg_table_name='tasks' and new.project_id is distinct from r.project_id then raise exception 'Tracker tasks must remain in their connected project';end if;end if;return new;end;$$;
revoke all on function nxt_private.guard_internal_tracker_work() from public,anon,authenticated;
create trigger zzz_internal_tracker_guard before update on public.projects for each row execute function nxt_private.guard_internal_tracker_work();create trigger zzz_internal_tracker_guard before update on public.tasks for each row execute function nxt_private.guard_internal_tracker_work();
create function nxt_private.bump_internal_task_version() returns trigger language plpgsql security definer set search_path='' as $$begin
 if tg_table_name='tasks' then update public.internal_tracker_tasks set version=version+1 where tenant_id=new.tenant_id and task_id=new.id;elsif new.kind='tasks' then update public.internal_tracker_tasks set version=version+1 where tenant_id=new.tenant_id and task_id=new.record_id;end if;return new;end;$$;
revoke all on function nxt_private.bump_internal_task_version() from public,anon,authenticated;
create trigger zzz_internal_tracker_version after update on public.tasks for each row execute function nxt_private.bump_internal_task_version();create trigger zzz_internal_flow_version after update on public.work_flow for each row execute function nxt_private.bump_internal_task_version();
create function public.create_internal_client_tracker(t uuid,operation_id uuid,v jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare c uuid;p uuid;tr uuid;oldrow public.internal_trackers;fprint text:=md5(v::text);e jsonb;w jsonb;ids uuid[]:='{}';seen text[]:='{}';project_due date;start_date date;internal_date date;client_date date;begin
 if auth.uid() is null or not public.is_staff(t) or not public.has_capability(t,'crm') or not public.has_capability(t,'delivery') then raise exception 'Client and delivery management access required';end if;
 if operation_id is null or jsonb_typeof(v) is distinct from 'object' or jsonb_typeof(v->'tasks') is distinct from 'array' or jsonb_array_length(v->'tasks') not between 1 and 100 then raise exception 'Provide 1–100 reviewed tasks';end if;
 if length(trim(coalesce(v->>'client_name',''))) not between 1 and 160 or length(trim(coalesce(v->>'tracker_name',''))) not between 1 and 160 or coalesce(v->>'document_id','') !~ '^[-A-Za-z0-9_]{3,80}$' or length(coalesce(v->>'revision','')) not between 1 and 80 or length(coalesce(v->>'source_name','')) not between 1 and 200 or length(coalesce(v->>'source_text','')) not between 1 and 150000 or length(coalesce(v->>'sla',''))>10000 then raise exception 'Check client, tracker and source details';end if;
 perform pg_advisory_xact_lock(hashtextextended(t::text||':client:'||lower(trim(v->>'client_name')),0));
 select * into oldrow from public.internal_trackers where tenant_id=t and (request_id=operation_id or fingerprint=fprint) limit 1;
 if found then if oldrow.fingerprint<>fprint then raise exception 'Operation ID already used for a different plan';end if;return jsonb_build_object('tracker_id',oldrow.id,'project_id',oldrow.project_id,'client_id',oldrow.client_id,'duplicate',true);end if;
 c:=nullif(v->>'client_id','')::uuid;
 if c is not null then if not exists(select 1 from public.clients where tenant_id=t and id=c and archived_at is null) then raise exception 'Choose an active client in this workspace';end if;
 else if exists(select 1 from public.clients where tenant_id=t and archived_at is null and lower(trim(title))=lower(trim(v->>'client_name'))) then raise exception 'Client already exists. Select its existing client record';end if;insert into public.clients(tenant_id,title,email) values(t,trim(v->>'client_name'),nullif(v->>'client_email','')) returning id into c;end if;
 if exists(select 1 from public.internal_trackers where tenant_id=t and client_id=c) then raise exception 'This client already has an internal tracker';end if;
 for e in select value from jsonb_array_elements(v->'tasks') loop
  if coalesce(e->>'key','') !~ '^[-A-Za-z0-9_]{1,80}$' or e->>'key'=any(seen) or length(trim(coalesce(e->>'title',''))) not between 1 and 160 or length(coalesce(e->>'description',''))>5000 or coalesce(e->>'priority','') not in ('P0','P1','P2','P3') or jsonb_typeof(e->'checks') is distinct from 'array' or jsonb_array_length(e->'checks') not between 1 and 50 or exists(select 1 from jsonb_array_elements(e->'checks') ch where jsonb_typeof(ch)<>'string' or length(trim(ch#>>'{}')) not between 1 and 1000) then raise exception 'Check task keys, scope, priority and acceptance criteria';end if;seen:=array_append(seen,e->>'key');
  if not exists(select 1 from public.staff_directory d join public.memberships m on m.tenant_id=d.tenant_id and m.user_id=d.user_id where d.tenant_id=t and d.user_id=(e->>'assignee_id')::uuid and m.role<>'client') then raise exception 'Choose an active staff owner for every task';end if;
  start_date:=(e->>'scheduled_start')::date;internal_date:=(e->>'internal_due')::date;client_date:=(e->>'client_due')::date;
  if start_date is null or internal_date is null or client_date is null or start_date>internal_date or internal_date>client_date then raise exception 'Confirm start, internal and client dates for every task';end if;project_due:=greatest(project_due,client_date);
 end loop;
 w:=public.save_work(t,'projects',jsonb_build_object('title',v->>'tracker_name','description','Internal tracker · '||(v->>'document_id')||' revision '||(v->>'revision'),'client_id',c,'scheduled_start',(select min((x->>'scheduled_start')::date) from jsonb_array_elements(v->'tasks') x),'internal_due',project_due,'client_due',project_due,'share_on_approval',false));p:=(w->>'id')::uuid;
 insert into public.internal_trackers(tenant_id,client_id,project_id,title,document_id,revision,source_name,source_text,sla,request_id,fingerprint) values(t,c,p,v->>'tracker_name',v->>'document_id',v->>'revision',v->>'source_name',v->>'source_text',coalesce(v->>'sla',''),operation_id,fprint) returning id into tr;
 for e in select value from jsonb_array_elements(v->'tasks') loop
  w:=public.save_work(t,'tasks',e||jsonb_build_object('client_id',c,'project_id',p,'share_on_approval',false,'source_name',v->>'source_name','source_excerpt',left(coalesce(e->>'source_excerpt',e->>'description'),10000),'depends_on',null));
  insert into public.internal_tracker_tasks(tenant_id,tracker_id,task_id,task_key,priority,checks) values(t,tr,(w->>'id')::uuid,e->>'key',e->>'priority',(select jsonb_agg(jsonb_build_object('text',x,'done',false)) from jsonb_array_elements_text(e->'checks') x));ids:=array_append(ids,(w->>'id')::uuid);
 end loop;return jsonb_build_object('tracker_id',tr,'project_id',p,'client_id',c,'task_ids',ids,'duplicate',false);end;$$;
revoke all on function public.create_internal_client_tracker(uuid,uuid,jsonb) from public,anon;grant execute on function public.create_internal_client_tracker(uuid,uuid,jsonb) to authenticated;
create function public.internal_tracker_snapshot(t uuid) returns jsonb language plpgsql security invoker set search_path='' as $$begin
 if auth.uid() is null or not public.is_staff(t) then raise exception 'Staff access required';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id','native:'||a.id,'native',true,'projectId',a.project_id,'clientId',a.client_id,'name',a.title,'available',true,'checkedAt',now(),'access',jsonb_build_object('canCreateTasks',false,'canApplyPlan',false,'canSchedule',public.has_capability(t,'delivery'),'name','','owners','[]'::jsonb),'data',jsonb_build_object('approvals','[]'::jsonb,'risks','[]'::jsonb,'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'version',b.version,'canEdit',public.has_capability(t,'delivery') or x.assignee_id=auth.uid(),'canSchedule',public.has_capability(t,'delivery'),'title',x.title,'description',x.description,'owner',d.name,'support','[]'::jsonb,'status',case x.status when 'todo' then 'Not started' when 'in_progress' then 'In progress' when 'under_review' then 'Awaiting review' when 'done' then 'Done' else x.status end,'priority',b.priority,'due',f.internal_due,'clientDue',x.due_date,'notes',b.notes,'action','','evidence',b.evidence,'updatedAt',greatest(x.updated_at,f.updated_at),'checks',b.checks,'dependencies','[]'::jsonb,'approvalIds','[]'::jsonb)) from public.internal_tracker_tasks b join public.tasks x on x.tenant_id=b.tenant_id and x.id=b.task_id join public.work_flow f on f.tenant_id=x.tenant_id and f.kind='tasks' and f.record_id=x.id left join public.staff_directory d on d.tenant_id=x.tenant_id and d.user_id=x.assignee_id where b.tenant_id=t and b.tracker_id=a.id and x.archived_at is null),'[]'::jsonb)))) from public.internal_trackers a join public.projects p on p.tenant_id=a.tenant_id and p.id=a.project_id where a.tenant_id=t and p.archived_at is null),'[]'::jsonb);end;$$;
revoke all on function public.internal_tracker_snapshot(uuid) from public,anon;grant execute on function public.internal_tracker_snapshot(uuid) to authenticated;
create function public.update_internal_tracker_task(t uuid,tr uuid,r uuid,expected_version integer,changes jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare x public.tasks;f public.work_flow;b public.internal_tracker_tasks;k text;next_checks jsonb;stage text;begin
 if auth.uid() is null or not public.is_staff(t) then raise exception 'Staff access required';end if;
 select * into x from public.tasks where tenant_id=t and id=r and archived_at is null for update;select * into f from public.work_flow where tenant_id=t and kind='tasks' and record_id=r;select * into b from public.internal_tracker_tasks where tenant_id=t and task_id=r and tracker_id=tr for update;
 if x.id is null or f.id is null or b.task_id is null then raise exception 'Tracker task unavailable';end if;
 if not (public.has_capability(t,'delivery') or x.assignee_id=auth.uid()) then raise exception 'Task access required';end if;if expected_version is distinct from b.version then raise exception 'This task has a newer version. Refresh before saving';end if;
 if jsonb_typeof(changes) is distinct from 'object' then raise exception 'Invalid update';end if;for k in select jsonb_object_keys(changes) loop if k not in ('status','notes','evidence','checks','due','clientDue','priority','dateChangeReason') then raise exception 'Unsupported task field';end if;end loop;
 next_checks:=coalesce(changes->'checks',b.checks);if jsonb_typeof(next_checks)<>'array' or jsonb_array_length(next_checks)<>jsonb_array_length(b.checks) or exists(select 1 from jsonb_array_elements(next_checks) with ordinality v(value,n) where value->>'text' is distinct from b.checks->(n::int-1)->>'text' or jsonb_typeof(value->'done') is distinct from 'boolean') then raise exception 'Only checklist completion may change';end if;
 if changes ?| array['due','clientDue','priority'] then if not public.has_capability(t,'delivery') then raise exception 'Schedule management required';end if;if changes ?| array['due','clientDue'] and length(trim(coalesce(changes->>'dateChangeReason','')))=0 then raise exception 'Record a deadline change reason';end if;
 perform public.save_work(t,'tasks',jsonb_build_object('id',r,'title',x.title,'description',x.description,'client_id',x.client_id,'project_id',x.project_id,'assignee_id',x.assignee_id,'scheduled_start',f.scheduled_start,'internal_due',coalesce(changes->>'due',f.internal_due::text),'client_due',coalesce(changes->>'clientDue',x.due_date::text),'share_on_approval',false));end if;
 if changes ? 'status' then stage:=case changes->>'status' when 'Not started' then 'not_started' when 'In progress' then 'in_progress' when 'Awaiting review' then 'under_review' when 'Done' then 'complete' else null end;if stage is null then raise exception 'Invalid task stage';end if;if stage='complete' and exists(select 1 from jsonb_array_elements(next_checks) c where c->>'done'<>'true') then raise exception 'Complete acceptance checks first';end if;perform public.move_task_stage(t,f.id,stage);end if;
 update public.internal_tracker_tasks set notes=coalesce(changes->>'notes',notes),evidence=coalesce(changes->>'evidence',evidence),checks=next_checks,priority=coalesce(changes->>'priority',priority),version=version+1 where tenant_id=t and task_id=r;return jsonb_build_object('saved',true,'id',r);end;$$;
revoke all on function public.update_internal_tracker_task(uuid,uuid,uuid,integer,jsonb) from public,anon;grant execute on function public.update_internal_tracker_task(uuid,uuid,uuid,integer,jsonb) to authenticated;
create function nxt_private.validate_tracker_link() returns trigger language plpgsql security invoker set search_path='' as $$declare a public.internal_trackers;begin
 if tg_table_name='internal_trackers' then
 if not exists(select 1 from public.projects p where p.tenant_id=new.tenant_id and p.id=new.project_id and p.client_id=new.client_id and not p.client_visible and p.archived_at is null) then raise exception 'Choose an internal project for this client';end if;
 else select * into a from public.internal_trackers where tenant_id=new.tenant_id and id=new.tracker_id;
 if a.id is null or not exists(select 1 from public.tasks x where x.tenant_id=new.tenant_id and x.id=new.task_id and x.client_id=a.client_id and x.project_id=a.project_id and not x.client_visible and x.archived_at is null) then raise exception 'Choose an internal task in this tracker';end if;end if;return new;end;$$;
revoke all on function nxt_private.validate_tracker_link() from public,anon,authenticated;
create trigger validate_tracker_link before insert on public.internal_trackers for each row execute function nxt_private.validate_tracker_link();
create trigger validate_tracker_task_link before insert on public.internal_tracker_tasks for each row execute function nxt_private.validate_tracker_link();
-- Metadata updates keep optimistic versions monotonic even through a direct Data API request.
create function nxt_private.guard_internal_tracker_metadata() returns trigger language plpgsql security invoker set search_path='' as $$begin
 if current_user not in ('postgres','supabase_admin') and new.priority is distinct from old.priority and not public.has_capability(new.tenant_id,'delivery') then raise exception 'Schedule management required';end if;
 if new.checks is distinct from old.checks and (jsonb_array_length(new.checks)<>jsonb_array_length(old.checks) or exists(select 1 from jsonb_array_elements(new.checks) with ordinality v(value,n) where value->>'text' is distinct from old.checks->(n::int-1)->>'text' or jsonb_typeof(value->'done') is distinct from 'boolean')) then raise exception 'Only checklist completion may change';end if;
 new.version:=old.version+1;return new;end;$$;
revoke all on function nxt_private.guard_internal_tracker_metadata() from public,anon,authenticated;
create trigger guard_internal_tracker_metadata before update on public.internal_tracker_tasks for each row execute function nxt_private.guard_internal_tracker_metadata();
create trigger internal_tracker_audit after insert or update on public.internal_trackers for each row execute function public.record_audit();
create function nxt_private.audit_internal_tracker_task() returns trigger language plpgsql security definer set search_path='' as $$begin
 insert into public.audit_events(tenant_id,actor_id,entity,record_id,action) values(new.tenant_id,auth.uid(),'internal_tracker_tasks',new.task_id,tg_op);return new;end;$$;
revoke all on function nxt_private.audit_internal_tracker_task() from public,anon,authenticated;
create trigger internal_tracker_task_audit after insert or update on public.internal_tracker_tasks for each row execute function nxt_private.audit_internal_tracker_task();
commit;
